pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testRegression_property() public {
        vm.deal(address(this), 10 ether);
        vm.deal(address(c), 1 ether);

        bool ok;
        try c.sendTo(address(0), 1) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok, "sendTo should revert when receiver is address(0)");
    }
}
